import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor matvec_forward(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <int THREADS>
__global__ void matvec_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int K)
{
  int m = blockIdx.x;
  int tid = threadIdx.x;

  // Full matrix / vector views via CuTe
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(K, Int<1>{}));
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(K), make_stride(Int<1>{}));

  // Row of A for this block
  Tensor gA = mA(m, _);   // (K)

  int K4 = K / 4;
  int tail_start = K4 * 4;

  float sum = 0.0f;

  if (K4 > 0) {
    // Vectorized view as float4 for coalesced, wide loads
    Tensor gA4 = recast<float4>(gA);
    Tensor gB4 = recast<float4>(mB);

    for (int i = tid; i < K4; i += THREADS) {
      float4 a = gA4(i);
      float4 b = gB4(i);
      sum += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
    }
  }

  // Handle remainder elements (K not divisible by 4)
  for (int i = tail_start + tid; i < K; i += THREADS) {
    sum += gA(i) * mB(i);
  }

  // Warp-level reduction
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    sum += __shfl_down_sync(0xffffffff, sum, offset);
  }

  __shared__ float shared[THREADS / 32];
  int lane = tid & 31;
  int wid  = tid >> 5;
  if (lane == 0) shared[wid] = sum;
  __syncthreads();

  if (wid == 0) {
    sum = (lane < (THREADS / 32)) ? shared[lane] : 0.0f;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      sum += __shfl_down_sync(0xffffffff, sum, offset);
    }
    if (lane == 0) {
      C[m] = sum;
    }
  }
}

torch::Tensor matvec_forward(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2, "A must be 2D (M, K)");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");

  int M = (int)A.size(0);
  int K = (int)A.size(1);

  auto B_flat = B.reshape({-1});
  TORCH_CHECK(B_flat.numel() == K, "B must have K elements");

  auto A_c = A.contiguous();
  auto B_c = B_flat.contiguous();

  auto C = torch::empty({M, 1}, A.options());

  constexpr int THREADS = 256;
  dim3 block(THREADS);
  dim3 grid((unsigned)M);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  matvec_kernel<THREADS><<<grid, block, 0, stream>>>(
      A_c.data_ptr<float>(),
      B_c.data_ptr<float>(),
      C.data_ptr<float>(),
      M, K
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "matvec_kernel launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

matvec_ext = load_inline(
    name="cute_matvec_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["matvec_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix-vector multiplication (C = A * B) implemented with a custom
    CuTe-based CUDA kernel. Each CUDA block computes one output element
    (dot product of a row of A with B) using vectorized float4 loads
    and a two-stage (warp + block) reduction.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = matvec_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.matvec_forward(A, B)

